public void processRequest(String token, String orderId) {
  // Step 1: Decode token to get claims (without verifying signature yet)
  JwtClaims claims = decode(token);

  // Step 2: Check if user is owner of the order
  if (!claims.getSubject().equals(getOrderOwner(orderId))) {
    throw new ForbiddenException();
  }

  // Step 3: Verify JWT Signature using Public Key
  verifySignature(token);

  // Step 4: Execute business logic
  updateOrder(orderId);
}
